# ---------------------------------------------------------------- Agoda 사진
BSIG = "https://q-xx.bstatic.com/xdata/images/hotel/max1024x768/{pid}.jpg?k={sig}&o="
PIX = "https://pix8.agoda.net/hotelImages/{hid}/0/{h}.jpg"

def pix(hid, hashes):
    return [PIX.format(hid=hid, h=h) for h in hashes.split()]

def bst(pairs):
    items = pairs.split() if isinstance(pairs, str) else list(pairs)
    return [BSIG.format(pid=p.split("|")[0], sig=p.split("|")[1]) for p in items]

